class Solution:
    def countShorterBehind(self, heights: List[int]) -> List[int]:
        n = len(heights)
        out = [0] * n
        for i in range(n):
            for j in range(i + 1, n):
                if heights[j] < heights[i]:
                    out[i] += 1
        return out

