class Solution:
    def countShorterBehind(self, heights: List[int]) -> List[int]:
        n = len(heights)
        out, idx, buf = [0] * n, list(range(n)), [0] * n
        def sort(lo, hi):
            if hi - lo <= 1:
                return
            mid = (lo + hi) // 2
            sort(lo, mid)
            sort(mid, hi)
            i, j, k = lo, mid, lo
            while i < mid:
                if j < hi and heights[idx[j]] < heights[idx[i]]:
                    buf[k] = idx[j]; j += 1
                else:
                    out[idx[i]] += j - mid
                    buf[k] = idx[i]; i += 1
                k += 1
            buf[k:k + hi - j] = idx[j:hi]
            idx[lo:hi] = buf[lo:hi]
        sort(0, n)
        return out

