class Solution {
    private int[] h, out, idx, buf;

    public int[] countShorterBehind(int[] heights) {
        int n = heights.length;
        h = heights;
        out = new int[n];
        idx = new int[n];
        buf = new int[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        sort(0, n);
        return out;
    }

    private void sort(int lo, int hi) {
        if (hi - lo <= 1) return;
        int mid = (lo + hi) >>> 1;
        sort(lo, mid);
        sort(mid, hi);
        int i = lo, j = mid, k = lo;
        while (i < mid) {
            if (j < hi && h[idx[j]] < h[idx[i]]) buf[k++] = idx[j++];
            else { out[idx[i]] += j - mid; buf[k++] = idx[i++]; }
        }
        while (j < hi) buf[k++] = idx[j++];
        System.arraycopy(buf, lo, idx, lo, hi - lo);
    }
}

