static void sort_idx(const int* h, int* out, int* idx, int* buf, int lo, int hi) {
    if (hi - lo <= 1) return;
    int mid = lo + (hi - lo) / 2;
    sort_idx(h, out, idx, buf, lo, mid);
    sort_idx(h, out, idx, buf, mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid) {
        if (j < hi && h[idx[j]] < h[idx[i]]) buf[k++] = idx[j++];
        else { out[idx[i]] += j - mid; buf[k++] = idx[i++]; }
    }
    while (j < hi) buf[k++] = idx[j++];
    memcpy(idx + lo, buf + lo, (hi - lo) * sizeof(int));
}

int* countShorterBehind(int* heights, int heightsSize, int* returnSize) {
    int n = heightsSize;
    int* out = calloc(n, sizeof(int));
    int* idx = malloc(n * sizeof(int));
    int* buf = malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) idx[i] = i;
    sort_idx(heights, out, idx, buf, 0, n);
    free(idx); free(buf);
    *returnSize = n;
    return out;
}

