class Solution:
    def countShorterBehind(self, heights: List[int]) -> List[int]:
        R = 20001
        tree = [0] * (R + 1)
        out = [0] * len(heights)
        for i in range(len(heights) - 1, -1, -1):
            h = heights[i] + 10001
            k, c = h - 1, 0
            while k > 0:
                c += tree[k]
                k -= k & -k
            out[i] = c
            while h <= R:
                tree[h] += 1
                h += h & -h
        return out

