class Solution {
    public int[] countShorterBehind(int[] heights) {
        int R = 20001;
        int[] tree = new int[R + 1], out = new int[heights.length];
        for (int i = heights.length - 1; i >= 0; i--) {
            int h = heights[i] + 10001;
            int c = 0;
            for (int k = h - 1; k > 0; k -= k & -k) c += tree[k];
            out[i] = c;
            for (int k = h; k <= R; k += k & -k) tree[k]++;
        }
        return out;
    }
}

